"""Coverage for defect #4: footnote markers landing after punctuation
instead of attached to the word.

Hebrew academic convention attaches a footnote marker to the word it
belongs to, before any trailing comma/period/etc. -- `word[^n],`, never
`word,[^n]`. Measured on a real generated article: 38 markers landed after
punctuation against 3 attached to the word. A caller's `after` anchor can
legitimately end in punctuation (copied verbatim from the surrounding
sentence), so `generate-docx.py`'s `add_para()` now trims the matched
anchor span back past any trailing `.,;:!?` before inserting the marker,
regardless of what the caller supplied.
"""

from __future__ import annotations

import importlib.util
import os
import re
import tempfile
import unittest
import zipfile

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPTS_DIR = os.path.join(ROOT_DIR, "src", "scripts")


def _load_generate_docx_module():
    script_path = os.path.join(SCRIPTS_DIR, "generate-docx.py")
    spec = importlib.util.spec_from_file_location("generate_docx_module_marker_test", script_path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _text_runs(document_xml):
    return re.findall(r"<w:t[^>]*>([^<]*)</w:t>", document_xml)


class FootnoteMarkerPlacementTests(unittest.TestCase):
    def setUp(self):
        self.module = _load_generate_docx_module()

    def _generate_and_read_document_xml(self, article_text, after, footnote_text):
        data = {
            "title": "בדיקה",
            "totalWords": 500,
            "format": {"isRtl": True},
            "sections": [
                {
                    "title": "מבוא",
                    "paragraphs": [
                        {"text": article_text, "footnotes": [{"after": after, "text": footnote_text}]}
                    ],
                }
            ],
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            output_path = os.path.join(tmpdir, "out.docx")
            self.module.generate_docx(data, output_path)
            with zipfile.ZipFile(output_path) as zf:
                return zf.read("word/document.xml").decode("utf-8")

    def test_marker_lands_before_comma_even_when_after_includes_it(self):
        # `after` deliberately includes the trailing comma, the exact shape
        # the reported defect measured: an anchor computed as "the N
        # characters before the marker", which naturally swallows punctuation.
        doc_xml = self._generate_and_read_document_xml(
            article_text="כפי שכתב שוורץ, הדברים ברורים.",
            after="כפי שכתב שוורץ,",
            footnote_text="מקור לדוגמה.",
        )
        self.assertIn("footnoteReference", doc_xml)
        runs = _text_runs(doc_xml)
        # The run immediately before the footnote reference must end at the
        # word, not the comma -- and the comma must survive, just pushed
        # into the following run.
        self.assertIn("כפי שכתב שוורץ", runs)
        self.assertNotIn("כפי שכתב שוורץ,", runs, "the comma must not be part of the run before the marker")
        following_text = "".join(runs[runs.index("כפי שכתב שוורץ") + 1 :])
        self.assertTrue(following_text.startswith(","), "the comma must survive, moved after the marker")

    def test_marker_lands_before_period_when_after_includes_it(self):
        doc_xml = self._generate_and_read_document_xml(
            article_text="זהו משפט חשוב.",
            after="זהו משפט חשוב.",
            footnote_text="מקור לדוגמה.",
        )
        runs = _text_runs(doc_xml)
        self.assertIn("זהו משפט חשוב", runs)
        self.assertNotIn("זהו משפט חשוב.", runs)

    def test_marker_still_placed_correctly_when_after_already_excludes_punctuation(self):
        # Regression guard: a well-formed anchor (no trailing punctuation)
        # must be completely unaffected by the trimming logic.
        doc_xml = self._generate_and_read_document_xml(
            article_text="כפי שכתב שוורץ, הדברים ברורים.",
            after="כפי שכתב שוורץ",
            footnote_text="מקור לדוגמה.",
        )
        runs = _text_runs(doc_xml)
        self.assertIn("כפי שכתב שוורץ", runs)
        self.assertIn("footnoteReference", doc_xml)

    def test_helper_never_shrinks_a_punctuation_only_span_to_empty(self):
        # Pathological input: trimming must never shrink the span to empty.
        module = self.module
        text = "word, more text"
        idx = text.find(",")
        end = idx + 1  # the span IS just the comma
        trimmed = module._anchor_end_before_trailing_punctuation(text, idx, end)
        self.assertEqual(trimmed, end, "a punctuation-only span must be left unchanged, not shrunk to empty")


if __name__ == "__main__":
    unittest.main()
